    14→
    15→import { Inst, IRProgram, Op, ir } from './ir';
    16→import { VM, Result as VMResult, Metrics } from './vm';
    17→import { PatternLibrary, Pattern } from './patterns';
    18→
    19→export interface ExecutionResult {
    20→  value: any;
    21→  cached: boolean;
    22→  cycles: number;
    23→  time: number;
    24→}
    25→
    26→export class V3Engine {
    27→  private vm = new VM();
    28→  private patterns = new PatternLibrary();
    29→  private execCount = 0;
    30→
    31→  /**
    32→   * AI가 intent를 실행 (완전 자동)
    33→   */
    34→  async execute(intent: string, variables?: Record<string, any>): Promise<ExecutionResult> {
    35→    this.execCount++;
    36→    console.log(`\n[${this.execCount}] "${intent}"`);
    37→
    38→    // 1. 패턴 검색
    39→    let pattern = this.patterns.find(intent);
    40→    let cached = false;
    41→
    42→    if (pattern) {
    43→      console.log(`  ✓ From cache (confidence: ${pattern.confidence.toFixed(2)})`);
    44→      cached = true;
    45→    } else {
    46→      // 유사 패턴 검색
    47→      const similar = this.patterns.findSimilar(intent, 0.6);
    48→      if (similar.length > 0) {
    49→        console.log(`  → Similar: ${similar[0].intent}`);
    50→      }
    51→
    52→      // 2. IR 생성
    53→      console.log(`  ⚙️  Generating IR...`);
    54→      const program = this.generateIR(intent);
    55→
    56→      // 패턴으로 저장
    57→      pattern = {
    58→        id: `p_${Date.now()}`,
    59→        intent,
    60→        ir: program.instructions,
    61→        variants: [],
    62→        stats: {
    63→          successCount: 0,
    64→          failCount: 0,
    65→          avgCycles: 0,
