    69→        confidence: 0.5
    70→      };
    71→
    72→      this.patterns.add(pattern);
    73→    }
    74→
    75→    // 3. IR 프로그램 생성
    76→    const program: IRProgram = {
    77→      id: pattern.id,
    78→      intent,
    79→      instructions: pattern.ir,
    80→      metadata: { variant: 0, generated: Date.now(), confidence: pattern.confidence }
    81→    };
    82→
    83→    // 4. VM 실행 (변수와 함께)
    84→    console.log(`  🚀 Running...`);
    85→    const vmResult = this.vm.run(program, variables);
    86→
    87→    // 6. 결과 처리
    88→    if (vmResult.ok) {
    89→      console.log(`  ✅ Result: ${JSON.stringify(vmResult.value)}`);
