    91→
    92→      // 7. 패턴 학습
    93→      this.patterns.update(pattern.id, vmResult.metrics, true);
    94→
    95→      return {
    96→        value: vmResult.value,
    97→        cached,
    98→        cycles: vmResult.metrics.cycles,
    99→        time: vmResult.metrics.time
   100→      };
   101→    } else {
   102→      console.log(`  ❌ Error: ${vmResult.error}`);
   103→
   104→      // 실패도 학습
   105→      this.patterns.update(pattern.id, vmResult.metrics, false);
   106→
   107→      throw new Error(vmResult.error);
