   111→  /**
   112→   * Intent → IR 자동 생성 (AI가 함)
   113→   */
   114→  private generateIR(intent: string): IRProgram {
   115→    const words = intent.toLowerCase().split(/\s+/);
   116→
   117→    const instructions: Inst[] = [];
   118→
   119→    // "sum array"
   120→    if (words.includes('sum')) {
   121→      instructions.push(ir.load('arr'));
   122→      instructions.push(ir.arrSum());
   123→    }
   124→    // "find max"
   125→    else if (words.includes('max')) {
   126→      instructions.push(ir.load('arr'));
   127→      instructions.push(ir.arrMax());
   128→    }
   129→    // "find min"
   130→    else if (words.includes('min')) {
   131→      instructions.push(ir.load('arr'));
   132→      instructions.push(ir.arrMin());
   133→    }
   134→    // "length"
   135→    else if (words.includes('length') || words.includes('size')) {
   136→      instructions.push(ir.load('arr'));
   137→      instructions.push(ir.arrLen());
   138→    }
   139→    // fallback: 숫자들
   140→    else {
   141→      const nums = intent.match(/\d+/g);
   142→      if (nums && nums.length > 0) {
   143→        for (const n of nums) {
   144→          instructions.push(ir.push(parseInt(n)));
   145→        }
   146→        if (words.includes('add') || words.includes('plus')) {
   147→          instructions.push({ op: Op.ADD });
   148→        }
   149→      }
   150→    }
   151→
   152→    if (instructions.length === 0) {
   153→      instructions.push(ir.push(0));
   154→    }
   155→
   156→    instructions.push(ir.halt());
   157→
   158→    return {
   159→      id: `prog_${Date.now()}`,
   160→      intent,
   161→      instructions,
   162→      metadata: { variant: 0, generated: Date.now(), confidence: 0.5 }
