   171→    console.log(`\n📊 Pattern Library:`);
   172→    console.log(`   Patterns: ${s.patterns}`);
   173→    console.log(`   Success rate: ${(s.successRate * 100).toFixed(1)}%`);
   174→    console.log(`   Avg cycles: ${s.avgCycles.toFixed(0)}`);
   175→  }
   176→}
