     1→/**
     2→ * Stack Machine (VM)
     3→ *
     4→ * IR을 직접 실행
     5→ * - 인간이 안 봐도 되고
     6→ * - AI가 바로 이해함
     7→ * - 성능 자동 측정
     8→ */
     9→
    10→import { Inst, IRProgram, Op } from './ir';
    11→
    12→export interface Metrics {
    13→  cycles: number;
    14→  time: number;
    15→  stackMax: number;
    16→}
    17→
    18→export interface Result {
    19→  ok: boolean;
    20→  value?: any;
    21→  error?: string;
    22→  metrics: Metrics;
    23→}
    24→
    25→export class VM {
    26→  private stack: any[] = [];
    27→  private vars: Map<string, any> = new Map();
    28→  private cycles = 0;
    29→  private stackMax = 0;
    30→
    31→  run(program: IRProgram, variables?: Record<string, any>): Result {
    32→    this.reset();
    33→
    34→    // 변수 초기화
    35→    if (variables) {
    36→      for (const [k, v] of Object.entries(variables)) {
    37→        this.vars.set(k, v);
    38→      }
    39→    }
    40→
    41→    const start = Date.now();
    42→
    43→    try {
    44→      for (let pc = 0; pc < program.instructions.length; pc++) {
    45→        const inst = program.instructions[pc];
    46→        this.execute(inst);
    47→        this.cycles++;
    48→        this.stackMax = Math.max(this.stackMax, this.stack.length);
    49→
    50→        if (this.cycles > 1000000) throw new Error('Cycle limit');
    51→        if (inst.op === Op.HALT) break;
    52→      }
    53→
    54→      const value = this.stack.length > 0 ? this.stack[0] : undefined;
    55→      return {
    56→        ok: true,
    57→        value,
    58→        metrics: {
    59→          cycles: this.cycles,
    60→          time: Date.now() - start,
    61→          stackMax: this.stackMax
    62→        }
    63→      };
    64→    } catch (e: any) {
    65→      return {
    66→        ok: false,
    67→        error: e.message,
    68→        metrics: {
    69→          cycles: this.cycles,
    70→          time: Date.now() - start,
    71→          stackMax: this.stackMax
    72→        }
    73→      };
    74→    }
    75→  }
    76→
    77→  private execute(inst: Inst) {
    78→    switch (inst.op) {
    79→      case Op.PUSH:
    80→        this.stack.push(inst.arg);
    81→        break;
    82→
    83→      case Op.POP:
    84→        this.stack.pop();
    85→        break;
    86→
    87→      case Op.ADD: {
    88→        const b = this.stack.pop();
    89→        const a = this.stack.pop();
    90→        this.stack.push(a + b);
    91→        break;
    92→      }
    93→
    94→      case Op.SUB: {
    95→        const b = this.stack.pop();
    96→        const a = this.stack.pop();
    97→        this.stack.push(a - b);
    98→        break;
    99→      }
   100→
   101→      case Op.MUL: {
   102→        const b = this.stack.pop();
   103→        const a = this.stack.pop();
   104→        this.stack.push(a * b);
   105→        break;
   106→      }
   107→
   108→      case Op.DIV: {
   109→        const b = this.stack.pop();
   110→        const a = this.stack.pop();
   111→        if (b === 0) throw new Error('Division by zero');
   112→        this.stack.push(a / b);
   113→        break;
   114→      }
   115→
   116→      case Op.ARR_SUM: {
   117→        const arr = this.stack.pop();
   118→        const sum = arr.reduce((a: any, b: any) => a + b, 0);
   119→        this.stack.push(sum);
   120→        break;
   121→      }
   122→
   123→      case Op.ARR_MAX: {
   124→        const arr = this.stack.pop();
   125→        this.stack.push(Math.max(...arr));
   126→        break;
   127→      }
   128→
   129→      case Op.ARR_MIN: {
   130→        const arr = this.stack.pop();
   131→        this.stack.push(Math.min(...arr));
   132→        break;
   133→      }
   134→
   135→      case Op.ARR_LEN: {
   136→        const arr = this.stack.pop();
   137→        this.stack.push(arr.length);
   138→        break;
   139→      }
   140→
   141→      case Op.LOAD: {
   142→        const val = this.vars.get(inst.arg as string);
   143→        this.stack.push(val);
   144→        break;
   145→      }
   146→
   147→      case Op.STORE: {
   148→        const val = this.stack[this.stack.length - 1];
   149→        this.vars.set(inst.arg as string, val);
   150→        break;
   151→      }
   152→
   153→      case Op.HALT:
   154→        // Stop execution
   155→        break;
   156→
   157→      default:
   158→        throw new Error(`Unknown op: ${inst.op}`);
   159→    }
   160→  }
   161→
   162→  private reset() {
   163→    this.stack = [];
   164→    this.vars.clear();
   165→    this.cycles = 0;
   166→    this.stackMax = 0;
   167→  }
   168→}
